6	/**
7	 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
8	 * the normalized last name and postcode (see {@link OwnerIdentityKey#householdId(String, String)}).
9	 * Every owner receives one, so owners sharing a last name and postcode automatically share the id —
10	 * there is no explicit linking and no dependency on {@code sharesHousehold} (that flag now only
11	 * bypasses the household duplicate block in {@link EnsureUniqueIdentity}).
12	 *
13	 * <p>Runs after {@link BuildOwner} within the create transaction and before {@link AssignHouseholdSize},
14	 * which counts the members sharing this computed id, and {@link SaveOwner}, which persists it.
15	 */
16	public class AssignHousehold {
17	
18	    public void service(@Val Owner owner) {
19	        owner.setHouseholdId(OwnerIdentityKey.householdIdOf(owner));
20	    }
21	}
