1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records, on the owner being created, the size of its household — the number of owners sharing the
9	 * same deterministic {@code householdId} once this create completes. The id is keyed on
10	 * {@code (normalizedLastName, postcode)} (see {@link OwnerIdentityKey}), so this counts existing owners
11	 * with the same last name and postcode plus one for the owner being created (not yet saved).
12	 *
13	 * <p>Runs after {@link AssignHousehold}, which has set the new owner's {@code householdId}, and before
14	 * {@link SaveOwner}.
15	 */
16	public class AssignHouseholdSize {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String householdId = owner.getHouseholdId();
20	        int count = 1; // the owner being created, not yet saved
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (householdId.equals(OwnerIdentityKey.householdIdOf(existing))) {
23	                count++;
24	            }
25	        }
26	        owner.setHouseholdSize(count);
27	    }
28	}
