7	/**
8	 * The IANA timezone name for an owner's locality. The locality (region) is the one derived by
9	 * {@link CustomerCodeRegion#of(Owner)}; it is mapped through a fixed region-to-timezone table
10	 * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). Regions absent
11	 * from the table (including the 'UNKNOWN' default) have no timezone and resolve to {@code null}.
12	 */
13	public final class LocalityTimezone {
14	
15	    /** Region -> IANA timezone name. */
16	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
17	            "NSW", "Australia/Sydney",
18	            "VIC", "Australia/Melbourne",
19	            "QLD", "Australia/Brisbane");
20	
21	    private LocalityTimezone() {
22	    }
23	
24	    /** The IANA timezone for {@code owner}'s locality, or {@code null} when its region has none. */
25	    public static String of(Owner owner) {
26	        return REGION_TIMEZONE.get(CustomerCodeRegion.of(owner));
27	    }
28	}
