1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's canonical region ('locality'). The postcode is preferred: the region is
7	 * looked up by postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back
8	 * to a fixed city-to-region table when the postcode is absent or in no known range. Cities absent
9	 * from the table (and postcodes in no range) resolve to 'UNKNOWN'.
10	 */
11	public final class LocalityLookup {
12	
13	    private static final String UNKNOWN = "UNKNOWN";
14	
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW",
17	            "Melbourne", "VIC",
18	            "Brisbane", "QLD");
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
22	            "NSW", new int[] {2000, 2099},
23	            "VIC", new int[] {3000, 3099},
24	            "QLD", new int[] {4000, 4099});
25	
26	    private LocalityLookup() {
27	    }
28	
29	    /** The canonical region for {@code city}, or 'UNKNOWN' when it is not in the table. */
30	    public static String regionOf(String city) {
31	        if (city == null) {
32	            return UNKNOWN;
33	        }
34	        return CITY_REGION.getOrDefault(city, UNKNOWN);
35	    }
36	
37	    /**
38	     * The canonical region, preferring the postcode: match {@code postcode} against the known
39	     * region ranges first, and only fall back to {@link #regionOf(String)} when the postcode is
40	     * absent or in no known range.
41	     */
42	    public static String regionOf(String city, String postcode) {
43	        String byPostcode = regionOfPostcode(postcode);
44	        return byPostcode != null ? byPostcode : regionOf(city);
45	    }
46	
47	    /** The region whose range contains {@code postcode}, or {@code null} when none does. */
48	    private static String regionOfPostcode(String postcode) {
49	        if (postcode == null) {
50	            return null;
51	        }
52	        int value;
53	        try {
54	            value = Integer.parseInt(postcode.trim());
55	        }
56	        catch (NumberFormatException ex) {
57	            return null;
58	        }
59	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
60	            int[] range = entry.getValue();
61	            if (value >= range[0] && value <= range[1]) {
62	                return entry.getKey();
63	            }
64	        }
65	        return null;
66	    }
67	}
