1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Household identity for owners. The {@code householdId} is now <em>deterministic</em>: it is derived
12	 * purely from the normalized last name and the postcode (see {@link #householdId(String, String)}), so
13	 * every owner sharing a last name and postcode computes the same value automatically — no explicit
14	 * linking is required. Duplicate detection ({@link EnsureUniqueIdentity}) and household size
15	 * ({@link AssignHouseholdSize}) both key off this computed id.
16	 *
17	 * <p>This class also exposes the read-only {@code identityKey} shown on the owner response,
18	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. That string embeds the
19	 * deterministic household id; it is descriptive only and no longer the basis of the duplicate check.
20	 *
21	 * <ul>
22	 * <li><b>normalizedTelephone</b> — the E.164 form (see {@link E164Telephone}); the stored telephone
23	 * is already E.164 and re-normalizing is idempotent.</li>
24	 * <li><b>email</b> — the lower-cased address, or empty when the owner has none.</li>
25	 * <li><b>householdId</b> — the owner's deterministic household id.</li>
26	 * </ul>
27	 */
28	public final class OwnerIdentityKey {
29	
30	    private OwnerIdentityKey() {
31	    }
32	
33	    /** The descriptive identity key of an already-built/stored owner, for the response. */
34	    public static String of(Owner owner) {
35	        return build(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
36	    }
37	
38	    /** The identity key from raw parts. Null telephone or email contribute an empty segment. */
39	    static String build(String telephone, String email, String householdId) {
40	        String tel = E164Telephone.toE164OrNull(telephone);
41	        return (tel == null ? "" : tel) + "|"
42	                + (email == null ? "" : email.trim().toLowerCase()) + "|"
43	                + (householdId == null ? "" : householdId);
44	    }
45	
46	    /** The deterministic household id of a stored/built owner, from its last name and postcode. */
47	    public static String householdIdOf(Owner owner) {
48	        return householdId(normalizeName(owner.getLastName()), normalizePostcode(owner.getPostcode()));
49	    }
50	
51	    /** The deterministic household id a create request would receive, from its last name and postcode. */
52	    static String householdIdOf(OwnerFieldsDto request) {
53	        return householdId(normalizeName(request.getLastName()), normalizePostcode(request.getPostcode()));
54	    }
55	
56	    /** Last-name normalization used for household grouping: trim, collapse whitespace, lower-case. */
57	    static String normalizeName(String value) {
58	        if (value == null) {
59	            return "";
60	        }
61	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
62	    }
63	
64	    /** Postcode normalization used for household grouping: trim; {@code null} becomes an empty string. */
65	    static String normalizePostcode(String value) {
66	        return value == null ? "" : value.trim();
67	    }
68	
69	    /**
70	     * Deterministic household id: the first 12 hex characters (upper-case) of SHA-256 over
71	     * {@code normalizedLastName + '|' + postcode}. Owners with the same last name and postcode share it.
72	     */
73	    static String householdId(String normalizedLastName, String postcode) {
74	        try {
75	            byte[] digest = MessageDigest.getInstance("SHA-256")
76	                    .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
77	            StringBuilder sb = new StringBuilder(12);
78	            for (int i = 0; i < 6; i++) {
79	                sb.append(String.format("%02x", digest[i]));
80	            }
81	            return sb.toString().toUpperCase();
82	        }
83	        catch (NoSuchAlgorithmException e) {
84	            throw new IllegalStateException("SHA-256 unavailable", e);
85	        }
86	    }
87	}
