1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field, before
13	 * {@link BuildOwner} runs. Binds the body without {@code @Valid} so the missing fields are
14	 * reported as an {@code errors} array (via {@link MissingOwnerFieldsException}) rather than as
15	 * bean-validation schema errors. This is the only step that binds the body; it republishes it
16	 * for {@link BuildOwner} to consume.
17	 *
18	 * <p>The address is normalized in place first (see {@link AddressNormalizer}), so the required-field
19	 * check rejects an address that is blank after normalization, and the stored/returned value and every
20	 * later address comparison see the normalized form.
21	 */
22	public class ValidateOwnerRequiredFields {
23	
24	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
25	            throws MissingOwnerFieldsException {
26	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
27	        List<String> missing = new ArrayList<>();
28	        if (isBlank(request.getFirstName())) {
29	            missing.add("firstName");
30	        }
31	        if (isBlank(request.getLastName())) {
32	            missing.add("lastName");
33	        }
34	        if (isBlank(request.getAddress())) {
35	            missing.add("address");
36	        }
37	        if (isBlank(request.getCity())) {
38	            missing.add("city");
39	        }
40	        if (isBlank(request.getTelephone())) {
41	            missing.add("telephone");
42	        }
43	        if (!missing.isEmpty()) {
44	            throw new MissingOwnerFieldsException(missing);
45	        }
46	        validated.set(request);
47	    }
48	
49	    private static boolean isBlank(String value) {
50	        return value == null || value.isBlank();
51	    }
52	}
