9	/**
10	 * Rejects a create request whose city already holds the maximum number of owners (50), so a single
11	 * city cannot grow without bound. City is compared case-insensitively with collapsed whitespace.
12	 * Runs before {@link BuildOwner}; a city already at capacity is a 409 via
13	 * {@link CityAtCapacityException}.
14	 */
15	public class EnsureCityCapacity {
16	
17	    private static final int CITY_CAPACITY = 50;
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws CityAtCapacityException {
21	        String city = normalize(request.getCity());
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (normalize(existing.getCity()).equals(city)) {
25	                count++;
26	            }
27	        }
28	        if (count >= CITY_CAPACITY) {
29	            throw new CityAtCapacityException(request.getCity());
30	        }
31	    }
32	
33	    private static String normalize(String value) {
34	        if (value == null) {
35	            return "";
36	        }
37	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
38	    }
39	}
